CREATE TABLE plugin_manifests (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, code text NOT NULL, version text NOT NULL, owner_kind text NOT NULL, entity_type text NOT NULL, item_type text, capabilities text[] NOT NULL DEFAULT '{}', data_policy jsonb NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), CHECK (code ~ '^[a-z][a-z0-9-]*$'), CHECK (version ~ '^[0-9]+\.[0-9]+\.[0-9]+(?:[-+][0-9A-Za-z.-]+)?$'), CHECK (owner_kind IN ('platform','tenant')), CHECK (capabilities <@ ARRAY['seed-import','api-import','spatial-query','map-render']::text[]), CHECK (jsonb_typeof(data_policy)='object'), UNIQUE(code,version), UNIQUE(id,code));
CREATE TABLE plugin_schema_versions (plugin_manifest_id bigint NOT NULL REFERENCES plugin_manifests(id) ON DELETE RESTRICT, schema_version integer NOT NULL, entity_fields jsonb NOT NULL, item_fields jsonb, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(plugin_manifest_id,schema_version), CHECK(schema_version>0), CHECK(jsonb_typeof(entity_fields)='object'), CHECK(item_fields IS NULL OR jsonb_typeof(item_fields)='object'));
CREATE TABLE sources (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, code text NOT NULL UNIQUE, origin_uri text NOT NULL, authorization_basis text NOT NULL, allowed_access_method text NOT NULL, attribution_text text NOT NULL, retention_policy text NOT NULL, deletion_policy text NOT NULL, refresh_policy text, takedown_contact text, created_at timestamptz NOT NULL DEFAULT now(), CHECK(code ~ '^[a-z][a-z0-9-]*$'), CHECK(origin_uri<>'' AND authorization_basis<>'' AND allowed_access_method<>'' AND retention_policy<>'' AND deletion_policy<>''));
CREATE TABLE import_runs (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, source_id bigint NOT NULL REFERENCES sources(id) ON DELETE RESTRICT, plugin_manifest_id bigint NOT NULL REFERENCES plugin_manifests(id) ON DELETE RESTRICT, operator_user_id bigint REFERENCES users(id) ON DELETE SET NULL, status text NOT NULL DEFAULT 'running', started_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz, input_version text NOT NULL, input_hash text NOT NULL, parser_version text NOT NULL, record_count integer NOT NULL DEFAULT 0, success_count integer NOT NULL DEFAULT 0, failure_count integer NOT NULL DEFAULT 0, failures jsonb NOT NULL DEFAULT '[]', CHECK(status IN ('running','succeeded','failed','cancelled')), CHECK((status='running' AND finished_at IS NULL) OR (status<>'running' AND finished_at IS NOT NULL)), CHECK(record_count>=0 AND success_count>=0 AND failure_count>=0 AND success_count+failure_count<=record_count), CHECK(jsonb_typeof(failures)='array'), UNIQUE(source_id,plugin_manifest_id,input_hash,parser_version));
CREATE TABLE source_records (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, source_id bigint NOT NULL REFERENCES sources(id) ON DELETE RESTRICT, import_run_id bigint NOT NULL REFERENCES import_runs(id) ON DELETE RESTRICT, external_id text NOT NULL, record_version text NOT NULL, retrieved_at timestamptz NOT NULL, content_hash text NOT NULL, parser_version text NOT NULL, source_coordinate_system text, coordinate_transform text, original_payload jsonb, normalized_evidence jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), CHECK(external_id<>'' AND record_version<>'' AND content_hash<>'' AND parser_version<>''), CHECK(source_coordinate_system IS NULL OR source_coordinate_system IN ('WGS84','GCJ-02','BD-09','other')), CHECK(jsonb_typeof(normalized_evidence)='object'), UNIQUE(source_id,external_id,record_version), UNIQUE(id,source_id));
CREATE INDEX source_records_import_run_id_idx ON source_records(import_run_id);
